/** Build the whole corpus. Deterministic; cheap enough to call per test. */
export function buildCorpus(): readonly CorpusScene[] {
  return SPECS.map(buildScene);
}

/** The scene ids, in corpus order. */
export const CORPUS_SCENE_IDS: readonly string[] = Object.freeze(SPECS.map((s) => s.id));

/**
 * The classifier parameters that carry a LENGTH and therefore have to be
 * restated in the scene's own unit. `slope` is a ratio, the support gates and
 * the greenness threshold are fractions, and `maxGridDim` is a cell count, so
 * none of them scale.
 */
export const LENGTH_PARAM_KEYS: readonly string[] = Object.freeze([
  'maxObjectSizeM',
  'elevThresholdM',
  'groundBandM',
  'lowVegBandM',
  'medVegBandM',
  'buildingRoughnessMaxM',
  'buildingMinHagM',
]);

/**
 * Restate metre-valued parameters in the scene's linear unit. A caller running
 * a foot cloud has to do exactly this; the corpus does it so the foot scene
 * measures the CLASSIFIER rather than measuring a caller who forgot.
 */
export function scaleLengthParams<T extends object>(
  params: T,
  scene: CorpusScene,
): Record<string, number> {
  const source = params as Readonly<Record<string, unknown>>;
  const out: Record<string, number> = {};
  for (const key of LENGTH_PARAM_KEYS) {
    const value = source[key];
    if (typeof value === 'number') out[key] = value / scene.unitToMetre;
  }
  return out;
}

// ── the hash pin ────────────────────────────────────────────────────────────

/**
 * One scene's digest: every coordinate as a millimetre integer, every label,
 * every colour and return byte, in point order. Hashing the QUANTISED integers
 * rather than the float text means the digest is a property of the geometry and
 * not of a formatter.
 */
export function sceneDigest(scene: CorpusScene): string {
  const parts: string[] = [
    scene.id,
    scene.unit,
    String(scene.count),
    String(scene.cellSize),
  ];
  for (let i = 0; i < scene.count; i++) {
    parts.push(
      `${Math.round(scene.xyz[i * 3] * 1000)},` +
        `${Math.round(scene.xyz[i * 3 + 1] * 1000)},` +
        `${Math.round(scene.xyz[i * 3 + 2] * 1000)},` +
        `${scene.truth[i]},` +
        `${scene.colors ? scene.colors[i * 3] : -1}:` +
        `${scene.colors ? scene.colors[i * 3 + 1] : -1}:` +
        `${scene.colors ? scene.colors[i * 3 + 2] : -1},` +
        `${scene.returnNumber ? scene.returnNumber[i] : -1}:` +
        `${scene.returnCount ? scene.returnCount[i] : -1}`,
    );
  }
  return `sha256:${sha256(parts.join('\n'))}`;
}

/**
 * The corpus digest: the version, then every scene's id and digest, folded into
 * one hash. Per-scene digests are hashed rather than one giant string so a
 * failure names the scene that moved.
 */
export function corpusDigest(scenes: readonly CorpusScene[]): string {
  const lines = [`corpus-v${CORPUS_VERSION}`];
  for (const scene of scenes) lines.push(`${scene.id} ${sceneDigest(scene)}`);
  return `sha256:${sha256(lines.join('\n'))}`;
}

// ── the reducer ─────────────────────────────────────────────────────────────

/** Per-class counts and rates. A metric with no denominator is null, never 0. */
export interface ClassMetrics {
  readonly code: number;
  /** Points whose TRUTH is this class. */
  readonly support: number;
  /** Points PREDICTED this class. */
  readonly predicted: number;
  readonly truePositive: number;
  readonly falsePositive: number;
  readonly falseNegative: number;
  readonly precision: number | null;
  readonly recall: number | null;
  readonly f1: number | null;
}

/** One scene's score. */
export interface SceneScore {
  readonly sceneId: string;
  readonly points: number;
  readonly byClass: readonly ClassMetrics[];
  /**
   * Mean F1 over {@link SCORED_CLASSES}, counting a class with support but no
   * defined F1 as 0 and skipping a class with neither support nor predictions.
   * Null when no scored class has either.
   */
  readonly macroF1: number | null;
  /** Fraction of points the classifier declined to name. */
  readonly unclassifiedRate: number;
  /**
   * Points predicted BUILDING whose truth is not building, over all points
   * whose truth is not building. A false-positive rate, so it does not move
   * when the scene's building count changes.
   */
  readonly falseBuildingRate: number | null;
  /** Points labelled {@link TRUTH_LOW_NOISE} that the run called ground. */
  readonly lowNoiseCalledGround: number;
  readonly lowNoisePoints: number;
}

/** Score one run of the classifier against a scene's labels. */
export function scoreScene(
  sceneId: string,
  truth: Uint8Array,
  predicted: Uint8Array,
): SceneScore {
  const n = Math.min(truth.length, predicted.length);
  const byClass: ClassMetrics[] = [];
  for (const code of SCORED_CLASSES) {
    let tp = 0;
    let fp = 0;
    let fn = 0;
    let support = 0;
    let predictedN = 0;
    for (let i = 0; i < n; i++) {
      const t = truth[i] === code;
      const p = predicted[i] === code;
      if (t) support++;
      if (p) predictedN++;
      if (t && p) tp++;
      else if (p) fp++;
      else if (t) fn++;
    }
    const precision = tp + fp > 0 ? tp / (tp + fp) : null;
    const recall = tp + fn > 0 ? tp / (tp + fn) : null;
    const f1 =
      precision !== null && recall !== null && precision + recall > 0
        ? (2 * precision * recall) / (precision + recall)
        : precision !== null && recall !== null
          ? 0
          : null;
    byClass.push({
      code,
      support,
      predicted: predictedN,
      truePositive: tp,
      falsePositive: fp,
      falseNegative: fn,
      precision,
      recall,
      f1,
    });
  }

  let f1Sum = 0;
  let f1N = 0;
  for (const m of byClass) {
    if (m.support === 0 && m.predicted === 0) continue;
    f1Sum += m.f1 ?? 0;
    f1N++;
  }

  let unclassified = 0;
  let notBuilding = 0;
  let falseBuilding = 0;
  let lowNoisePoints = 0;
  let lowNoiseCalledGround = 0;
  for (let i = 0; i < n; i++) {
    if (predicted[i] === PREDICTED_UNCLASSIFIED) unclassified++;
    if (truth[i] !== TRUTH_BUILDING) {
      notBuilding++;
      if (predicted[i] === TRUTH_BUILDING) falseBuilding++;
    }
    if (truth[i] === TRUTH_LOW_NOISE) {
      lowNoisePoints++;
      if (predicted[i] === TRUTH_GROUND) lowNoiseCalledGround++;
    }
  }

  return {
    sceneId,
    points: n,
    byClass,
    macroF1: f1N > 0 ? f1Sum / f1N : null,
    unclassifiedRate: n > 0 ? unclassified / n : 0,
    falseBuildingRate: notBuilding > 0 ? falseBuilding / notBuilding : null,
    lowNoiseCalledGround,
    lowNoisePoints,
  };
}

/**
 * Pool per-class counts across scenes and rebuild the rates from the totals.
 * Pooling the COUNTS rather than averaging the rates keeps a small scene from
 * weighing the same as a large one.
 */
export function poolScores(scores: readonly SceneScore[]): SceneScore {
  const byCode = new Map<number, { tp: number; fp: number; fn: number; support: number; predicted: number }>();
  for (const code of SCORED_CLASSES) {
    byCode.set(code, { tp: 0, fp: 0, fn: 0, support: 0, predicted: 0 });
  }
  let points = 0;
  let unclassified = 0;
  let notBuilding = 0;
  let falseBuilding = 0;
  let lowNoisePoints = 0;
  let lowNoiseCalledGround = 0;
  for (const s of scores) {
    points += s.points;
    unclassified += Math.round(s.unclassifiedRate * s.points);
    lowNoisePoints += s.lowNoisePoints;
    lowNoiseCalledGround += s.lowNoiseCalledGround;
    for (const m of s.byClass) {
      const acc = byCode.get(m.code);
      if (!acc) continue;
      acc.tp += m.truePositive;
      acc.fp += m.falsePositive;
      acc.fn += m.falseNegative;
      acc.support += m.support;
      acc.predicted += m.predicted;
      if (m.code === TRUTH_BUILDING) {
        notBuilding += s.points - m.support;
        falseBuilding += m.falsePositive;
      }
    }
  }

  const byClass: ClassMetrics[] = SCORED_CLASSES.map((code) => {
    const acc = byCode.get(code)!;
    const precision = acc.tp + acc.fp > 0 ? acc.tp / (acc.tp + acc.fp) : null;
    const recall = acc.tp + acc.fn > 0 ? acc.tp / (acc.tp + acc.fn) : null;
    const f1 =
      precision !== null && recall !== null && precision + recall > 0
        ? (2 * precision * recall) / (precision + recall)
        : precision !== null && recall !== null
          ? 0
          : null;
    return {
      code,
      support: acc.support,
      predicted: acc.predicted,
      truePositive: acc.tp,
      falsePositive: acc.fp,
      falseNegative: acc.fn,
      precision,
      recall,
      f1,
    };
  });

  let f1Sum = 0;
  let f1N = 0;
  for (const m of byClass) {
    if (m.support === 0 && m.predicted === 0) continue;
    f1Sum += m.f1 ?? 0;
    f1N++;
  }

  return {
    sceneId: 'pooled',
    points,
    byClass,
    macroF1: f1N > 0 ? f1Sum / f1N : null,
    unclassifiedRate: points > 0 ? unclassified / points : 0,
    falseBuildingRate: notBuilding > 0 ? falseBuilding / notBuilding : null,
    lowNoiseCalledGround,
    lowNoisePoints,
  };
}
